package com.externalvisuals.modules;
import com.externalvisuals.module.Module; import com.externalvisuals.setting.*; import java.util.*; import net.minecraft.entity.Entity; import net.minecraft.util.math.Vec3d;
public class DamageNumbers extends Module { public final SliderSetting scale=addSetting(new SliderSetting("Scale",1.0,.5,2,.1)); public final SliderSetting lifetime=addSetting(new SliderSetting("Lifetime",35,10,80,1)); public final BooleanSetting critColor=addSetting(new BooleanSetting("Crit Color",true)); public final List<Entry> entries=new ArrayList<>(); public DamageNumbers(){super("Damage Numbers");} public void add(Entity e,float damage,boolean crit){entries.add(new Entry(new Vec3d(e.getX(),e.getY()+e.getHeight()+.25,e.getZ()),damage,crit,System.currentTimeMillis()));} public void tick(){entries.removeIf(x->System.currentTimeMillis()-x.time>lifetime.getValue()*50); for(Entry x:entries)x.pos=x.pos.add(0,.002,0);} public static class Entry{public Vec3d pos;public final float damage;public final boolean crit;public final long time;Entry(Vec3d p,float d,boolean c,long t){pos=p;damage=d;crit=c;time=t;}}}
